import assert from 'node:assert/strict'
import { readFile } from 'node:fs/promises'
import test from 'node:test'

test('the bundle keeps the workflow group and publishes the sidebar client', async () => {
  const patch = await readFile(new URL('../cordis.patch.yml', import.meta.url), 'utf8')
  assert.match(patch, /id: feature-dev-suite/)
  assert.match(patch, /name: cordis:group/)
  assert.match(patch, /workflowEngine: true/)
  assert.match(patch, /name: dsh-feature-dev-suite/)
  const manifest = JSON.parse(await readFile(new URL('../package.json', import.meta.url), 'utf8'))
  assert.equal(manifest.name, 'dsh-feature-dev-suite')
  assert.equal(manifest.dsh.bundle.patch, './cordis.patch.yml')
  assert.equal(manifest.dsh.client.platform, 'web')
  assert.equal(manifest.exports['.'], './lib/index.js')
  assert.equal(manifest.exports['./client'], './lib/client.js')
  const client = await readFile(new URL('../lib/client.js', import.meta.url), 'utf8')
  assert.match(client, /window\.__ModuleLoader__\.load/)
  assert.match(client, /sidebar\.panellist/)
  assert.match(client, /name: 'main'/)
  assert.match(client, /功能开发 \/ Feature Dev/)
  assert.match(client, /advanceEnabled/)
  assert.match(client, /execute_in_chat/)
  assert.match(client, /needs_session/)
  assert.match(client, /chatCall/)
  assert.match(client, /expectedArtifacts/)
  assert.match(client, /artifact\.missing/)
  const host = await readFile(new URL('../lib/index.js', import.meta.url), 'utf8')
  assert.match(host, /feature_dev/)
  assert.match(host, /featureSummary is required for start/)
  const readme = await readFile(new URL('../README.zh.md', import.meta.url), 'utf8')
  assert.match(readme, /功能开发/)
  assert.match(readme, /sidebar\.panellist/)
  assert.match(readme, /会话/)
  assert.match(readme, /allowBuilds/)
  assert.match(readme, /0\.1\.3/)
  assert.match(readme, /implementTools/)
  assert.match(readme, /feature-dev-offline/)
  const english = await readFile(new URL('../README.md', import.meta.url), 'utf8')
  assert.match(english, /session agent/)
  assert.match(english, /0\.1\.3/)
  assert.match(english, /implementTools/)
  assert.match(english, /feature-dev-offline/)
  const offline = await readFile(new URL('../docs/feature-dev-offline.md', import.meta.url), 'utf8')
  assert.match(offline, /fd-folder-diff-v1/)
  assert.match(offline, /02-design-review\.md/)
  assert.match(offline, /06-full\.diff/)
})
